#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/stopfile_lifecycle_v23_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/runtime_control.py "$BK/" || true
cp -a companyos/runtime/service_supervisor.py "$BK/" || true
echo "" | base64 -d > "$PREFIX/tmp/v23_runtime.py"
python "$PREFIX/tmp/v23_runtime.py"
echo "" | base64 -d > "$PREFIX/tmp/v23_supervisor.py"
python "$PREFIX/tmp/v23_supervisor.py"
echo "" | base64 -d > tests/test_stopfile_lifecycle_v23.py
echo "" | base64 -d > scripts/companyos_verify_stopfile_v23
chmod +x scripts/companyos_verify_stopfile_v23
python -m py_compile companyos/runtime/runtime_control.py companyos/runtime/service_supervisor.py tests/test_stopfile_lifecycle_v23.py
python -m unittest tests.test_stopfile_lifecycle_v23 -v
scripts/companyos_verify_stopfile_v23 | tee .companyos_runtime/stopfile_lifecycle_v23.log
git add companyos/runtime/runtime_control.py companyos/runtime/service_supervisor.py scripts/companyos_verify_stopfile_v23 tests/test_stopfile_lifecycle_v23.py
git diff --cached --quiet || git commit -m "Repair stale stop-file lifecycle on supervisor start"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true
echo "BACKUP=$BK"
echo "COMPANYOS_STOPFILE_LIFECYCLE_REPAIR_V23=PASS"
